import{_ as e,c as s,o as n,ae as o}from"./chunks/framework.Bi6zybwU.js";const u=JSON.parse('{"title":"Other Design Settings","description":"Other Design Settings","frontmatter":{"title":"Other Design Settings","description":"Other Design Settings"},"headers":[],"relativePath":"guide/styling-design/other-design-settings.md","filePath":"guide/styling-design/other-design-settings.md"}'),i={name:"guide/styling-design/other-design-settings.md"};function r(a,t,g,l,h,c){return n(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="other-design-settings" tabindex="-1">Other Design Settings <a class="header-anchor" href="#other-design-settings" aria-label="Permalink to &quot;Other Design Settings&quot;">​</a></h1><p>The last feature among the three styling tabs is the **Other **option. This tab contains numerous sections, such as</p><ul><li><strong>Pagination Items Per Page</strong></li><li><strong>Pagination Position</strong></li><li><strong>Search Bar Position</strong></li><li><strong>Select Sorting Method</strong></li><li><strong>Row Details</strong></li><li><strong>Toggle Position</strong></li><li><strong>Extra CSS Class for the Table</strong></li><li><strong>Sticky Header</strong></li><li><strong>Table</strong> <strong>Font</strong> <strong>Settings</strong><img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-table-design-Other-tab-383x1024.webp" alt="New Ui table design Other tab"></li><li>The <strong>Pagination Items Per Page</strong> allows you to restrict the number of rows you want to view in the table. <strong>Pagination Position</strong> specifies the location or display of the pagination number. To know more, <strong><a href="https://ninjatables.com/docs/pagination/" target="_blank" rel="noreferrer">check</a></strong> here.</li><li>The <strong>Search Bar Position</strong> determines where the search bar will be placed; the search input can also be set to full width.</li><li><strong>Select Sorting Method</strong> enables you to sort data in various ways. To know more about it, <strong><a href="https://ninjatables.com/docs/sorting/" target="_blank" rel="noreferrer">go</a></strong> here.</li><li><strong>Row Details</strong> configures the responsiveness. **Toggle Position **is used during a responsive breakdown where the <strong>+</strong> icon will show at the first/second visible column.</li><li><strong>Extra CSS Class</strong> for the table allows you to use additional CSS code if you want to include it.</li><li>If you enable the <strong>Sticky Header</strong> option, the table’s header position remains fixed while scrolling.</li><li><strong>Table Font settings</strong> is a feature where the user can choose the font family &amp; font size according to their needs. To know more, <strong><a href="https://ninjatables.com/docs/table-font-settings/" target="_blank" rel="noreferrer">click</a></strong> here.</li></ul>',3)])])}const b=e(i,[["render",r]]);export{u as __pageData,b as default};
